def metric(data: pd.DataFrame) -> float:
    anti_ttb_count = 0
    total = 0
    for _, row in data.iterrows():
        a = row['option_a_ratings']
        b = row['option_b_ratings']
        if sum(a) == sum(b):
            if a[0] > b[0]:
                ttb_choice = 0
            elif b[0] > a[0]:
                ttb_choice = 1
            else:
                continue
            if row['response'] != ttb_choice:
                anti_ttb_count += 1
            total += 1
    if total == 0:
        return 0.0
    return anti_ttb_count / total

